-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9944, 23, 'Schulsozialarbeit und Schulpsychologie als feste Teams gegen Mobbing und Konflikte ausbauen (Land)', 'Dauerhaft präsentes Fachpersonal kann Konflikte früh bearbeiten und Betroffene stützen. Die Studienlage zur Schulsozialarbeit ist uneinheitlich, Fachkräfte fehlen, die Finanzierung ist Ländersache.', 'gemischt', null, 'land', null, true, 'blind'),
  (9945, 23, 'Schulpsychologische und psychosoziale Beratung für Schüler ausbauen (Land)', 'Mehr Beratung lindert Belastungsfolgen, ändert aber den Leistungs- und Prüfungsdruck selbst kaum. Fachkräftemangel bei Schulpsychologie bremst den Ausbau.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9765869/', 'land', null, true, 'blind'),
  (9946, 23, 'Schulische Programme zu Resilienz, psychischer Gesundheit und Stressbewältigung (Land)', 'Programme stärken den Umgang mit Stress, beseitigen den Druck aber nicht. Einzelne Studien finden Effekte, größere Studien zu Achtsamkeit in Schulen fanden keinen Nutzen. Per Erlass und Fortbildung rasch machbar.', 'gemischt', 'https://doi.org/10.1016/j.jaac.2017.07.780', 'land', null, true, 'blind'),
  (9947, 23, 'Mental-Health-Coaches an Schulen ausbauen (Bund)', 'Niedrigschwellige Coaches lindern Belastungsfolgen, Wirkung auf den Druck selbst kaum untersucht. Bund kann mit Programmgeld beitragen, Schulen sind Ländersache.', 'offen', null, 'bund', null, true, 'blind'),
  (9948, 23, 'Lehrpläne entschlacken, Stoffdruck verringern (Land)', 'Weniger Stoff kann Zeitdruck mindern und Raum für Förderung schaffen. Ob Belastung messbar sinkt, ist kaum untersucht; Wirkung hängt von der Umsetzung im Unterricht ab. Landesrecht, schnell machbar.', 'offen', null, 'land', null, true, 'blind'),
  (9949, 23, 'Ziffernnoten reduzieren oder durch Lernrückmeldungen ersetzen (Land)', 'Weniger Noten nehmen einen Kern des Leistungsdrucks; Studien zeigen teils weniger Prüfungsangst und mehr Lernfreude, andere keinen Effekt. Übergänge und Abschlüsse brauchen weiter Bewertungen, KMK-Abstimmung nötig.', 'gemischt', 'https://doi.org/10.1080/10627197.2025.2455128', 'land', null, true, 'blind'),
  (9950, 23, 'Leistungsbewertung und Prüfungsformate unbestimmt reformieren (Land)', 'Ohne konkrete Vorgaben (Zahl der Arbeiten, Ersatz von Noten) bleibt offen, ob der Druck sinkt. Wirkung flexibler Formate auf Stress kaum untersucht. Landesrecht, rasch umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (9951, 23, 'Abitur nach neun Jahren bzw. längerer Gymnasialweg (Land)', 'Mehr Zeit kann Zeitdruck am Gymnasium senken. Studien zur Verkürzung auf G8 finden teils mehr Belastung, teils kaum Effekte auf Gesundheit; Wirkung begrenzt auf Gymnasiasten. Landesrecht, aber Mehrkosten.', 'gemischt', 'https://doi.org/10.1016/j.econedurev.2017.03.003', 'land', null, true, 'blind'),
  (9952, 23, 'Hausaufgaben reduzieren oder durch begleitete Lernzeit in der Schule ersetzen (Land)', 'Weniger Hausaufgaben mindern Belastung am Nachmittag; Nutzen von Hausaufgaben in der Grundschule gilt als gering. Begleitete Lernzeit braucht zusätzliches Personal und Geld.', 'gemischt', null, 'land', null, true, 'blind'),
  (9953, 23, 'Druck beim Übergang auf weiterführende Schulen verringern (Land)', 'Weniger Auslese in den Klassen 4 bis 6 kann Übergangsdruck mindern; Belege zur Wirkung auf Gesundheit fehlen weitgehend. Landesrecht, kurzfristig umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (9954, 23, 'Sitzenbleiben abschaffen oder freiwillig machen (Land)', 'Klassenwiederholung bringt laut Forschung wenig Lernzuwachs und kann belasten; ob Abschaffung Druck senkt, ist kaum belegt. Landesrecht, schnell machbar.', 'gemischt', 'https://doi.org/10.1016/j.edurev.2021.100401', 'land', null, true, 'blind'),
  (9955, 23, 'Längeres gemeinsames Lernen, mehr Gemeinschaftsschulen (Land)', 'Späte Aufteilung kann Selektionsdruck mindern; Studien zur Wirkung auf Stress und Wohlbefinden sind uneinheitlich. Strukturreform braucht mehrere Jahre und Schulraum.', 'gemischt', 'https://doi.org/10.3102/00346543221100850', 'land', null, true, 'blind'),
  (9956, 23, 'Leistungsanforderungen und Auslese verschärfen (Land)', 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'gemischt', 'https://www.nber.org/papers/w11124', 'land', null, true, 'blind'),
  (9957, 23, 'Leistungsanforderungen, Vergleichsarbeiten und Notenpflicht verschärfen (Bund)', 'Mehr Vergleichs- und Prüfungsdruck mindert Belastung nicht, kann sie erhöhen. Bund hat kaum Zuständigkeit für Schulen, nur über KMK-Einigung der Länder.', 'gemischt', null, 'bund', null, true, 'blind'),
  (9958, 23, 'Kleinere Klassen (Land)', 'Kleinere Klassen geben Lehrkräften mehr Raum für Beziehungen; Wirkung auf Mobbing ist wenig belegt, Effekte auf Lernen sind klein. Erfordert viele zusätzliche Lehrkräfte, die fehlen.', 'gemischt', null, 'land', null, true, 'blind'),
  (9959, 23, 'Fortbildung der Lehrkräfte zu Mobbing, Gewalt, Diskriminierung und Cybermobbing (Land)', 'Geschulte Lehrkräfte greifen häufiger und wirksamer ein, ein Kernfaktor gegen Verfestigung. Reine Einzelschulungen ohne schulweites Konzept zeigen kleinere Effekte. Landesrecht, rasch machbar.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'land', null, true, 'blind'),
  (9960, 23, 'Allgemeine verpflichtende Lehrkräftefortbildung ausbauen (Land)', 'Mehr Qualifizierung kann den Umgang mit Konflikten verbessern, ohne Mobbing-Bezug bleibt die Wirkung indirekt und kaum untersucht. Landesrecht, rasch machbar.', 'offen', null, 'land', null, true, 'blind'),
  (9961, 23, 'Lehrkräfteausbildung praxisnäher gestalten (Land)', 'Mehr Praxis und Klassenführung können Handlungssicherheit erhöhen; Wirkung auf Mobbing nicht untersucht, wirkt erst mit Jahren Verzug. Hochschulreformen und Neugründungen brauchen mehrere Jahre.', 'offen', null, 'land', null, true, 'blind'),
  (9962, 23, 'Lehrkräftebildung bundesweit praxisnäher und diskriminierungssensibel weiterentwickeln (Bund)', 'Qualifizierung kann Handlungssicherheit verbessern, Wirkung auf Mobbing indirekt. Lehrerbildung ist Ländersache; Bund kann nur über Programme und Vereinbarungen beitragen.', 'offen', null, 'bund', null, true, 'blind'),
  (9963, 23, 'Anti-Mobbing-Teams und Beratungslehrkräfte an jeder Schule (Land)', 'Feste Ansprechteams sind Teil wirksamer schulweiter Konzepte. Ohne Fortbildung und Rückhalt der Schulleitung bleibt der Effekt klein. Landesrecht, mit wenig Mehrkosten umsetzbar.', 'gemischt', null, 'land', null, true, 'blind'),
  (9964, 23, 'Unabhängige Beschwerde- und Meldestellen für Schulen (Land)', 'Zusätzliche Meldewege senken die Hürde, Vorfälle zu melden; ob dies Mobbing verringert, ist kaum untersucht, die Stelle ersetzt kein Handeln an der Schule. Landesrecht, schnell machbar.', 'offen', 'https://doi.org/10.1177/10901981211073734', 'land', null, true, 'blind'),
  (9965, 23, 'Schutzkonzepte gegen Gewalt und Diskriminierung für Schulen verpflichtend machen (Land)', 'Verbindliche Konzepte bündeln Prävention, Meldewege und Intervention; Wirkung hängt von der Umsetzung ab und ist kaum untersucht. Landesrecht, rasch machbar.', 'offen', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5363950/', 'land', null, true, 'blind'),
  (9966, 23, 'Schulweite Programme zur Prävention von Mobbing, Cybermobbing und Gewalt (Land)', 'Mehrere Meta-Analysen finden bei schulweiten Programmen weniger Mobbing. Wirkung hängt von Qualität und Dauer ab, Einzelaktionen haben wenig Effekt. Landesrecht, finanzierbar.', 'belegt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356322/', 'land', null, true, 'blind'),
  (9967, 23, 'Aufklärungsprojekte und Aktionstage gegen Diskriminierung und abwertende Haltungen (Land)', 'Projekte können Normen verändern, kurze Einzelaktionen zeigen aber oft nur geringe, kurzlebige Effekte. Landesrecht, rasch machbar.', 'gemischt', 'https://doi.org/10.1146/annurev-psych-071620-030619', 'land', null, true, 'blind'),
  (9968, 23, 'Soziales und emotionales Lernen, Konfliktlösung und Empathie im Unterricht (Land)', 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'belegt', 'https://doi.org/10.1111/cdev.13968', 'land', null, true, 'blind'),
  (9969, 23, 'Klassenrat, Klassenleiterstunde und Klassengemeinschaft stärken (Land)', 'Regelmäßige Klassenrunden bearbeiten Normen und Konflikte und sind Teil wirksamer Anti-Mobbing-Konzepte. Als Einzelmaßnahme sind die Effekte uneinheitlich. Landesrecht, kaum Kosten.', 'gemischt', null, 'land', null, true, 'blind'),
  (9970, 23, 'Sanktionen und Schulverweise bei Gewalt verschärfen (Land)', 'Klare Konsequenzen können Normen stützen; Studien zu Null-Toleranz-Ansätzen und Ausschluss zeigen aber keine Verbesserung des Schulklimas. Landesrecht, rasch machbar.', 'gemischt', 'https://doi.org/10.1037/0003-066x.63.9.852', 'land', null, true, 'blind'),
  (9971, 23, 'Verbindliche, abgestufte Interventions- und Reaktionswege bei Mobbing und Gewalt (Land)', 'Verbindliches Eingreifen verhindert Verfestigung; klare Verfahren erhöhen die Handlungssicherheit. Wirkung hängt von Umsetzung und Schulung ab. Landesrecht, schnell machbar.', 'gemischt', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5363950/', 'land', null, true, 'blind'),
  (9972, 23, 'Plattformpflichten und Altersgrenzen für Social Media (Bund)', 'Plattformregeln erreichen Cybermobbing an der Quelle, Wirkung von Altersgrenzen ist noch kaum untersucht. Weitgehend EU-Recht (DSA), nationale Alleingänge stoßen an Grenzen.', 'offen', 'https://www.leopoldina.org/fileadmin/Daten/Publikationen/Dokumente/2025_Diskussionspapier_Soziale_Medien.pdf', 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
