insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9973, 23, 11, null, 'Ein Maßnahmenpaket zum Gesundheits- und Jugendmedienschutz bei Social Media vorlegen, nach wissenschaftlicher Bewertung', '{2303}', null, 1, 3, null, 'Angekündigt ist zunächst nur eine wissenschaftliche Bewertung mit späterem Maßnahmenpaket; konkrete Wirkung auf Cybermobbing offen. Bund kann dies im Rahmen des Jugendmedienschutzes rasch erarbeiten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=66', null, 'offen', '2026-10-14', false, true, 'blind'),
  (9974, 23, 11, null, 'Verbindliche Vergleichsarbeiten und Lernstandserhebungen einführen bzw. ausbauen', '{2304}', 9957, 0, 1, null, 'Mehr Vergleichs- und Prüfungsdruck mindert Belastung nicht, kann sie erhöhen. Bund hat kaum Zuständigkeit für Schulen, nur über KMK-Einigung der Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=65', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (9975, 23, 11, 'BE', 'Themen wie Gleichberechtigung, Grenzen und gewaltfreie Konfliktlösung sollen früh in Kitas und Schulen vermittelt werden.', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=11', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (9976, 23, 11, 'BE', 'Ganztagsangebote an Grundschulen qualitativ ausbauen; sie sollen auch soziales Lernen fördern.', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=56', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (9977, 23, 11, 'BE', 'Vorschule (Kita-Chancenjahr) stärken und ausbauen; soziale Kompetenzen sollen ein Schwerpunkt sein.', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=56', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (9978, 23, 11, 'BE', 'Strategie gegen Gewalt an Schulen, die Prävention, Intervention und Repression verbindet.', '{2302,2301}', 9971, 2, 3, null, 'Verbindliches Eingreifen verhindert Verfestigung; klare Verfahren erhöhen die Handlungssicherheit. Wirkung hängt von Umsetzung und Schulung ab. Landesrecht, schnell machbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=60', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5363950/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9979, 23, 11, 'BE', 'Zusammenarbeit von Schule mit Kinder- und Jugendhilfe sowie Jugendsozialarbeit ausbauen; Kontext Gewalt an Schulen.', '{2301,2302}', 9944, 2, 2, null, 'Dauerhaft präsentes Fachpersonal kann Konflikte früh bearbeiten und Betroffene stützen. Die Studienlage zur Schulsozialarbeit ist uneinheitlich, Fachkräfte fehlen, die Finanzierung ist Ländersache.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=60', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (9980, 23, 11, 'BE', 'Lehrkräfte sollen Aus-, Fort- und Weiterbildung systematisch durchlaufen und regelmäßig fortgebildet werden.', '{2302}', 9960, 1, 3, null, 'Mehr Qualifizierung kann den Umgang mit Konflikten verbessern, ohne Mobbing-Bezug bleibt die Wirkung indirekt und kaum untersucht. Landesrecht, rasch machbar.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=58', null, 'offen', '2026-10-14', false, true, 'blind'),
  (9981, 23, 11, 'BE', 'Landesprogramm für Mental Health und Ausbau schulpsychologischer Angebote; Resilienzförderung im Schulalltag.', '{2304}', 9945, 1, 2, null, 'Mehr Beratung lindert Belastungsfolgen, ändert aber den Leistungs- und Prüfungsdruck selbst kaum. Fachkräftemangel bei Schulpsychologie bremst den Ausbau.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=61', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9765869/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9982, 23, 11, 'MV', 'Werteerziehung als Teil des Schulauftrags: zivilisierter Umgang, Respekt und positives Gemeinschaftserleben lernen.', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=51', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (9983, 23, 11, 'MV', 'Absenken von Anforderungen und Leistungsstandards stoppen und umkehren.', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=50', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9984, 23, 11, 'MV', 'Verschärfte Zugangsvoraussetzungen zum Gymnasium, alternativ über einen Potenzialtest.', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=48', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9985, 23, 11, 'MV', 'Gezielte Förderung von Kindern mit Lernrückständen, parallel zu höheren Leistungsanforderungen.', '{2304}', null, 1, 3, null, 'Gezielte Förderung kann Überforderung bei Lernrückständen mindern. Die Förderung wird aber an höhere Leistungsanforderungen gekoppelt, die den Druck erhöhen können. Landesrecht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=51', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (9986, 23, 11, 'ST', 'Oberschule: Sozialverhalten und Basiskompetenzen neben Praxis- und Wirtschaftsbildung stärken', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=22', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (9987, 23, 11, 'ST', 'Lehrkräfteausbildung stärker auf Praxisphasen, Referendariat und Kompetenzanforderungen ausrichten', '{2302}', 9961, 1, 2, null, 'Mehr Praxis und Klassenführung können Handlungssicherheit erhöhen; Wirkung auf Mobbing nicht untersucht, wirkt erst mit Jahren Verzug. Hochschulreformen und Neugründungen brauchen mehrere Jahre.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=25', null, 'offen', '2026-10-14', false, true, 'blind'),
  (9988, 23, 11, 'ST', 'Psychische Gesundheit und Suizidprävention gemeinsam mit Schulen und Kommunen stärken', '{2304}', 9946, 1, 3, null, 'Programme stärken den Umgang mit Stress, beseitigen den Druck aber nicht. Einzelne Studien finden Effekte, größere Studien zu Achtsamkeit in Schulen fanden keinen Nutzen. Per Erlass und Fortbildung rasch machbar.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=28', 'https://doi.org/10.1016/j.jaac.2017.07.780', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9989, 23, 12, null, 'Anreize für Schutzkonzepte in allen Einrichtungen schaffen, in denen Kinder und Jugendliche regelmäßig sind; Recht auf Aufwachsen ohne Gewalt.', '{2301,2302}', null, 1, 2, null, 'Anreize für Schutzkonzepte können Prävention und Meldewege verbreiten; Wirkung kaum untersucht und abhängig von der Umsetzung vor Ort. Bund kann mit Programmen und Geld beitragen, Schulen sind Ländersache.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=28', null, 'offen', '2026-10-14', false, true, 'blind'),
  (9990, 23, 12, null, 'Plattformbetreiber verpflichten, illegale Inhalte zu entfernen; Jugendschutz im Netz durch Altersverifikation stärken.', '{2303}', 9972, 1, 1, null, 'Plattformregeln erreichen Cybermobbing an der Quelle, Wirkung von Altersgrenzen ist noch kaum untersucht. Weitgehend EU-Recht (DSA), nationale Alleingänge stoßen an Grenzen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=45', 'https://www.leopoldina.org/fileadmin/Daten/Publikationen/Dokumente/2025_Diskussionspapier_Soziale_Medien.pdf', 'offen', '2026-10-14', false, true, 'blind'),
  (9991, 23, 12, null, 'Digitales Gewaltschutzgesetz gegen digitale Gewalt schaffen.', '{2303}', null, 1, 2, null, 'Ein Gesetz gegen digitale Gewalt kann Betroffenen Rechte geben (z. B. Sperrung, Auskunft), Wirkung auf Schul-Cybermobbing kaum untersucht. Bund zuständig, Abstimmung mit EU-Plattformrecht nötig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=44', null, 'offen', '2026-10-14', false, true, 'blind'),
  (9992, 23, 12, 'BE', 'Jede Schule soll ein Anti-Mobbing-Team erhalten.', '{2302,2301}', 9963, 2, 3, null, 'Feste Ansprechteams sind Teil wirksamer schulweiter Konzepte. Ohne Fortbildung und Rückhalt der Schulleitung bleibt der Effekt klein. Landesrecht, mit wenig Mehrkosten umsetzbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (9993, 23, 12, 'BE', 'Ausbau multiprofessioneller Teams, etwa mehr Stellen für Schulsozialarbeit und Schulpsychologie, gegen Mobbing und Ausgrenzung.', '{2301,2302}', 9944, 2, 2, null, 'Dauerhaft präsentes Fachpersonal kann Konflikte früh bearbeiten und Betroffene stützen. Die Studienlage zur Schulsozialarbeit ist uneinheitlich, Fachkräfte fehlen, die Finanzierung ist Ländersache.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (9994, 23, 12, 'BE', 'Eine unabhängige Beschwerdestelle für Schulen und Kitas beim Parlament ansiedeln.', '{2302}', 9964, 1, 3, null, 'Zusätzliche Meldewege senken die Hürde, Vorfälle zu melden; ob dies Mobbing verringert, ist kaum untersucht, die Stelle ersetzt kein Handeln an der Schule. Landesrecht, schnell machbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://doi.org/10.1177/10901981211073734', 'offen', '2026-10-14', false, true, 'blind'),
  (9995, 23, 12, 'BE', 'Schüler*innenvertretungen und Klassenrat als Instrumente für Partizipation und Konfliktlösung stärken.', '{2301}', 9969, 2, 3, null, 'Regelmäßige Klassenrunden bearbeiten Normen und Konflikte und sind Teil wirksamer Anti-Mobbing-Konzepte. Als Einzelmaßnahme sind die Effekte uneinheitlich. Landesrecht, kaum Kosten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (9996, 23, 12, 'BE', 'Empathie als Wahlpflichtfach einführen.', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (9997, 23, 12, 'BE', 'Queere Bildung in Schulen und Jugendarbeit stärken, um Hass und Gewalt vorzubeugen.', '{2301}', 9967, 1, 3, null, 'Projekte können Normen verändern, kurze Einzelaktionen zeigen aber oft nur geringe, kurzlebige Effekte. Landesrecht, rasch machbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=49', 'https://doi.org/10.1146/annurev-psych-071620-030619', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9998, 23, 12, 'BE', 'Fortbildungen und verpflichtende Module zu Diskriminierung für pädagogische Fachkräfte.', '{2302}', 9959, 2, 3, null, 'Geschulte Lehrkräfte greifen häufiger und wirksamer ein, ein Kernfaktor gegen Verfestigung. Reine Einzelschulungen ohne schulweites Konzept zeigen kleinere Effekte. Landesrecht, rasch machbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=41', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (9999, 23, 12, 'BE', 'Rahmenlehrpläne verschlanken und die Stundentafel flexibilisieren, damit die Schule weniger Stoffdruck erzeugt.', '{2304}', 9948, 1, 3, null, 'Weniger Stoff kann Zeitdruck mindern und Raum für Förderung schaffen. Ob Belastung messbar sinkt, ist kaum untersucht; Wirkung hängt von der Umsetzung im Unterricht ab. Landesrecht, schnell machbar.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=40', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10000, 23, 12, 'BE', 'Mentale Gesundheit aller Beteiligten an Schulen stärken, unter anderem durch mehr Schulpsychologie und Gesundheitsfachkräfte.', '{2304}', 9945, 1, 2, null, 'Mehr Beratung lindert Belastungsfolgen, ändert aber den Leistungs- und Prüfungsdruck selbst kaum. Fachkräftemangel bei Schulpsychologie bremst den Ausbau.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=42', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9765869/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10001, 23, 12, 'MV', 'Präventionsangebote gegen Mobbing, Cybermobbing und Gewalt sowie zur psychischen Gesundheit junger Menschen weiter unterstützen', '{2301}', 9966, 2, 3, null, 'Mehrere Meta-Analysen finden bei schulweiten Programmen weniger Mobbing. Wirkung hängt von Qualität und Dauer ab, Einzelaktionen haben wenig Effekt. Landesrecht, finanzierbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=36', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356322/', 'belegt', '2026-10-14', false, true, 'blind'),
  (10002, 23, 12, 'MV', 'Konfliktlösung als Alltagskompetenz in der schulischen Bildung stärken', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=69', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (10003, 23, 12, 'MV', 'Fort- und Weiterbildung der Lehrkräfte ausbauen', '{2302}', 9960, 1, 3, null, 'Mehr Qualifizierung kann den Umgang mit Konflikten verbessern, ohne Mobbing-Bezug bleibt die Wirkung indirekt und kaum untersucht. Landesrecht, rasch machbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10004, 23, 12, 'MV', 'Leistungsbewertung reformieren, Rückmeldungen lernförderlich gestalten', '{2304}', 9950, 1, 3, null, 'Ohne konkrete Vorgaben (Zahl der Arbeiten, Ersatz von Noten) bleibt offen, ob der Druck sinkt. Wirkung flexibler Formate auf Stress kaum untersucht. Landesrecht, rasch umsetzbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10005, 23, 12, 'MV', 'Flexibleres Prüfungssystem mit mehreren Prüfungszeiträumen, um Stress zu reduzieren (berufliche Bildung)', '{2304}', 9950, 1, 3, null, 'Ohne konkrete Vorgaben (Zahl der Arbeiten, Ersatz von Noten) bleibt offen, ob der Druck sinkt. Wirkung flexibler Formate auf Stress kaum untersucht. Landesrecht, rasch umsetzbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=70', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10006, 23, 12, 'MV', 'Gesundheitsvorsorge sowie Gewalt- und Extremismusprävention an Schulen stärken', '{2301}', 9966, 2, 3, null, 'Mehrere Meta-Analysen finden bei schulweiten Programmen weniger Mobbing. Wirkung hängt von Qualität und Dauer ab, Einzelaktionen haben wenig Effekt. Landesrecht, finanzierbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=68', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356322/', 'belegt', '2026-10-14', false, true, 'blind'),
  (10007, 23, 12, 'ST', 'Präventive und demokratiepädagogische Projekte an Schulen gegen abwertende Haltungen unter Schülern intensivieren und dauerhaft fördern', '{2301}', 9967, 1, 3, null, 'Projekte können Normen verändern, kurze Einzelaktionen zeigen aber oft nur geringe, kurzlebige Effekte. Landesrecht, rasch machbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=36', 'https://doi.org/10.1146/annurev-psych-071620-030619', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10008, 23, 12, 'ST', 'Schutzkonzepte gegen Gewalt und Diskriminierung für Schulen und weitere Einrichtungen verpflichtend machen', '{2301}', 9965, 1, 3, null, 'Verbindliche Konzepte bündeln Prävention, Meldewege und Intervention; Wirkung hängt von der Umsetzung ab und ist kaum untersucht. Landesrecht, rasch machbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=32', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5363950/', 'offen', '2026-10-14', false, true, 'blind'),
  (10009, 23, 12, 'ST', 'Regelmäßige Fortbildungen für Fachkräfte verbindlich machen, damit Prävention im Alltag wirkt', '{2302}', 9960, 1, 3, null, 'Mehr Qualifizierung kann den Umgang mit Konflikten verbessern, ohne Mobbing-Bezug bleibt die Wirkung indirekt und kaum untersucht. Landesrecht, rasch machbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=33', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10010, 23, 12, 'ST', 'Qualifizierung zu Beratungslehrkräften wird neu gestartet', '{2302}', 9963, 2, 3, null, 'Feste Ansprechteams sind Teil wirksamer schulweiter Konzepte. Ohne Fortbildung und Rückhalt der Schulleitung bleibt der Effekt klein. Landesrecht, mit wenig Mehrkosten umsetzbar.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=18', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10011, 23, 13, null, 'Diskriminierungssensible Fortbildungen in der Kindertagespflege und in der Lehrer*innenausbildung', '{2302}', 9962, 1, 2, null, 'Qualifizierung kann Handlungssicherheit verbessern, Wirkung auf Mobbing indirekt. Lehrerbildung ist Ländersache; Bund kann nur über Programme und Vereinbarungen beitragen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=76', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10012, 23, 13, null, 'Angebote der Mental Health Coaches an Schulen ausbauen', '{2304}', 9947, 1, 2, null, 'Niedrigschwellige Coaches lindern Belastungsfolgen, Wirkung auf den Druck selbst kaum untersucht. Bund kann mit Programmgeld beitragen, Schulen sind Ländersache.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=77', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10013, 23, 13, null, 'Voreinstellungen für sichere Dienste und Geräte für Eltern und Kinder, dazu Datenschutzregeln für Kinder und Jugendliche', '{2303}', null, 1, 2, null, 'Sichere Voreinstellungen können Risiken für Kinder auf Plattformen senken; Wirkung auf Cybermobbing kaum untersucht. Jugendschutzrecht ist Bundessache, Pflichten für Dienste sind aber EU-rechtlich mitgeregelt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=85', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10014, 23, 13, 'BE', 'Unabhängige Beschwerdestelle gegen Diskriminierung an Schulen, eingerichtet unter dem Dach der LADG-Ombudsstelle', '{2302}', 9964, 1, 3, null, 'Zusätzliche Meldewege senken die Hürde, Vorfälle zu melden; ob dies Mobbing verringert, ist kaum untersucht, die Stelle ersetzt kein Handeln an der Schule. Landesrecht, schnell machbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=136', 'https://doi.org/10.1177/10901981211073734', 'offen', '2026-10-14', false, true, 'blind'),
  (10015, 23, 13, 'BE', 'Bedarfsgerechte, praxisnahe und qualitätsgesicherte Fortbildungen für pädagogisches Personal, schulweit umgesetzt und evaluiert', '{2302}', 9960, 1, 3, null, 'Mehr Qualifizierung kann den Umgang mit Konflikten verbessern, ohne Mobbing-Bezug bleibt die Wirkung indirekt und kaum untersucht. Landesrecht, rasch machbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=194', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10016, 23, 13, 'BE', 'Klassenräte an allen Schulen und in allen Klassen verbindlich umsetzen', '{2301}', 9969, 2, 3, null, 'Regelmäßige Klassenrunden bearbeiten Normen und Konflikte und sind Teil wirksamer Anti-Mobbing-Konzepte. Als Einzelmaßnahme sind die Effekte uneinheitlich. Landesrecht, kaum Kosten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=185', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10017, 23, 13, 'BE', 'Queere Bildungsprojekte und Präventionsangebote gegen Diskriminierung als feste Angebote an Schulen etablieren und ausbauen', '{2301}', 9967, 1, 3, null, 'Projekte können Normen verändern, kurze Einzelaktionen zeigen aber oft nur geringe, kurzlebige Effekte. Landesrecht, rasch machbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=193', 'https://doi.org/10.1146/annurev-psych-071620-030619', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10018, 23, 13, 'BE', 'Verlässliche Betreuung in der Grundschule um mindestens eine Stunde bis 14:30 Uhr verlängern, mit Lernbegleitung, damit keine Hausaufgaben zu Hause nötig sind', '{2304}', 9952, 1, 2, null, 'Weniger Hausaufgaben mindern Belastung am Nachmittag; Nutzen von Hausaufgaben in der Grundschule gilt als gering. Begleitete Lernzeit braucht zusätzliches Personal und Geld.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=191', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10019, 23, 13, 'BE', 'Gemeinschaftsschulen berlinweit verdoppeln, um Schulstress zu verringern', '{2304}', 9955, 1, 2, null, 'Späte Aufteilung kann Selektionsdruck mindern; Studien zur Wirkung auf Stress und Wohlbefinden sind uneinheitlich. Strukturreform braucht mehrere Jahre und Schulraum.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=220', 'https://doi.org/10.3102/00346543221100850', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10020, 23, 13, 'BE', 'Übergang von der Grund- zur Oberschule reformieren, damit Schüler*innen der Klassen 4 bis 6 mit weniger Druck zur Schule gehen', '{2304}', 9953, 1, 3, null, 'Weniger Auslese in den Klassen 4 bis 6 kann Übergangsdruck mindern; Belege zur Wirkung auf Gesundheit fehlen weitgehend. Landesrecht, kurzfristig umsetzbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=188', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10021, 23, 13, 'BE', 'Mentale Gesundheit in Schulen stärken: Hilfesysteme verknüpfen, Aufklärung fördern, Wohlbefinden als Qualitätsmerkmal festlegen', '{2304}', 9946, 1, 3, null, 'Programme stärken den Umgang mit Stress, beseitigen den Druck aber nicht. Einzelne Studien finden Effekte, größere Studien zu Achtsamkeit in Schulen fanden keinen Nutzen. Per Erlass und Fortbildung rasch machbar.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=192', 'https://doi.org/10.1016/j.jaac.2017.07.780', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10022, 23, 13, 'BE', 'Übergang zu zeitgemäßen Prüfungsformaten und kompetenzbasiertem Lernfeedback statt Ziffernoten', '{2304}', 9949, 2, 2, null, 'Weniger Noten nehmen einen Kern des Leistungsdrucks; Studien zeigen teils weniger Prüfungsangst und mehr Lernfreude, andere keinen Effekt. Übergänge und Abschlüsse brauchen weiter Bewertungen, KMK-Abstimmung nötig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=187', 'https://doi.org/10.1080/10627197.2025.2455128', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10023, 23, 13, 'MV', 'Medienbildung für Lehrkräfte stärken, damit Schulen besser auf Mobbing im Netz und Desinformation reagieren können.', '{2302}', 9959, 2, 3, null, 'Geschulte Lehrkräfte greifen häufiger und wirksamer ein, ein Kernfaktor gegen Verfestigung. Reine Einzelschulungen ohne schulweites Konzept zeigen kleinere Effekte. Landesrecht, rasch machbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10024, 23, 13, 'MV', 'Qualität des Lehramtsstudiums und des Vorbereitungsdienstes verbessern, damit Lehrkräfte besser qualifiziert sind.', '{2302}', 9961, 1, 2, null, 'Mehr Praxis und Klassenführung können Handlungssicherheit erhöhen; Wirkung auf Mobbing nicht untersucht, wirkt erst mit Jahren Verzug. Hochschulreformen und Neugründungen brauchen mehrere Jahre.', 'https://gruene-mv.de/?wpdmdl=33772#page=42', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10025, 23, 13, 'MV', 'Verpflichtende Weiterbildungen für Pädagog*innen und Schulpsycholog*innen, um Mehrfachdiskriminierung queerer Personen zu verhindern.', '{2302}', 9959, 2, 3, null, 'Geschulte Lehrkräfte greifen häufiger und wirksamer ein, ein Kernfaktor gegen Verfestigung. Reine Einzelschulungen ohne schulweites Konzept zeigen kleinere Effekte. Landesrecht, rasch machbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=87', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10026, 23, 13, 'MV', 'Präventionskonzepte gegen sexualisierte und digitale Gewalt an Schulen einführen.', '{2301}', 9966, 2, 3, null, 'Mehrere Meta-Analysen finden bei schulweiten Programmen weniger Mobbing. Wirkung hängt von Qualität und Dauer ab, Einzelaktionen haben wenig Effekt. Landesrecht, finanzierbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=82', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356322/', 'belegt', '2026-10-14', false, true, 'blind'),
  (10027, 23, 13, 'MV', 'Demokratiebildung und Medienkompetenz in Lehrplänen und pädagogischer Ausbildung verankern, unter anderem zu Cybermobbing.', '{2301}', 9966, 2, 3, null, 'Mehrere Meta-Analysen finden bei schulweiten Programmen weniger Mobbing. Wirkung hängt von Qualität und Dauer ab, Einzelaktionen haben wenig Effekt. Landesrecht, finanzierbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356322/', 'belegt', '2026-10-14', false, true, 'blind'),
  (10028, 23, 13, 'MV', 'Psychosoziale Beratung an Schulen ermöglichen und Programme zur mentalen Gesundheit von Schüler*innen ausbauen.', '{2304}', 9945, 1, 2, null, 'Mehr Beratung lindert Belastungsfolgen, ändert aber den Leistungs- und Prüfungsdruck selbst kaum. Fachkräftemangel bei Schulpsychologie bremst den Ausbau.', 'https://gruene-mv.de/?wpdmdl=33772#page=44', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9765869/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10029, 23, 13, 'MV', 'Rahmenpläne entschlacken und mehr Wahlfreiheit bei Bewertungsmethoden schaffen.', '{2304}', 9948, 1, 3, null, 'Weniger Stoff kann Zeitdruck mindern und Raum für Förderung schaffen. Ob Belastung messbar sinkt, ist kaum untersucht; Wirkung hängt von der Umsetzung im Unterricht ab. Landesrecht, schnell machbar.', 'https://gruene-mv.de/?wpdmdl=33772#page=43', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10030, 23, 13, 'MV', 'Abitur wahlweise in 12 oder 13 Jahren ermöglichen.', '{2304}', 9951, 1, 3, null, 'Mehr Zeit kann Zeitdruck am Gymnasium senken. Studien zur Verkürzung auf G8 finden teils mehr Belastung, teils kaum Effekte auf Gesundheit; Wirkung begrenzt auf Gymnasiasten. Landesrecht, aber Mehrkosten.', 'https://gruene-mv.de/?wpdmdl=33772#page=43', 'https://doi.org/10.1016/j.econedurev.2017.03.003', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10031, 23, 13, 'ST', 'Landesaktionsprogramm gegen Mobbing mit Aktionswochen, Aktionstagen und Konzeptarbeit an Schulen', '{2301}', 9967, 1, 3, null, 'Projekte können Normen verändern, kurze Einzelaktionen zeigen aber oft nur geringe, kurzlebige Effekte. Landesrecht, rasch machbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=63', 'https://doi.org/10.1146/annurev-psych-071620-030619', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10032, 23, 13, 'ST', 'Schulklima mit Kooperation und Miteinander im Schulgesetz verankern', '{2301}', 9969, 2, 3, null, 'Regelmäßige Klassenrunden bearbeiten Normen und Konflikte und sind Teil wirksamer Anti-Mobbing-Konzepte. Als Einzelmaßnahme sind die Effekte uneinheitlich. Landesrecht, kaum Kosten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=63', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10033, 23, 13, 'ST', 'Klassenräte und Schüler*innenparlamente als weitere Mitbestimmungsgremien einführen', '{2301}', 9969, 2, 3, null, 'Regelmäßige Klassenrunden bearbeiten Normen und Konflikte und sind Teil wirksamer Anti-Mobbing-Konzepte. Als Einzelmaßnahme sind die Effekte uneinheitlich. Landesrecht, kaum Kosten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10034, 23, 13, 'ST', 'Unabhängige landesweite Ombudsstelle für Übergriffe an Schulen mit anonymer Meldung und Beratung', '{2302}', 9964, 1, 3, null, 'Zusätzliche Meldewege senken die Hürde, Vorfälle zu melden; ob dies Mobbing verringert, ist kaum untersucht, die Stelle ersetzt kein Handeln an der Schule. Landesrecht, schnell machbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', 'https://doi.org/10.1177/10901981211073734', 'offen', '2026-10-14', false, true, 'blind'),
  (10035, 23, 13, 'ST', 'Verbindliche regelmäßige Fortbildungen für Lehrkräfte zu Diskriminierung und Übergriffen', '{2302}', 9959, 2, 3, null, 'Geschulte Lehrkräfte greifen häufiger und wirksamer ein, ein Kernfaktor gegen Verfestigung. Reine Einzelschulungen ohne schulweites Konzept zeigen kleinere Effekte. Landesrecht, rasch machbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=64', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10036, 23, 13, 'ST', 'Stressmanagement, Achtsamkeit und Entspannung als Bestandteil des Sportunterrichts', '{2304}', 9946, 1, 3, null, 'Programme stärken den Umgang mit Stress, beseitigen den Druck aber nicht. Einzelne Studien finden Effekte, größere Studien zu Achtsamkeit in Schulen fanden keinen Nutzen. Per Erlass und Fortbildung rasch machbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=56', 'https://doi.org/10.1016/j.jaac.2017.07.780', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10037, 23, 13, 'ST', 'Deutliche Verringerung der Benotung und Abschaffung von Noten in Neigungs- und Talentfächern', '{2304}', 9949, 2, 2, null, 'Weniger Noten nehmen einen Kern des Leistungsdrucks; Studien zeigen teils weniger Prüfungsangst und mehr Lernfreude, andere keinen Effekt. Übergänge und Abschlüsse brauchen weiter Bewertungen, KMK-Abstimmung nötig.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', 'https://doi.org/10.1080/10627197.2025.2455128', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10038, 23, 13, 'ST', 'Sitzenbleiben soll im Wesentlichen eine freiwillige Entscheidung von Schüler*innen und Eltern sein', '{2304}', 9954, 1, 3, null, 'Klassenwiederholung bringt laut Forschung wenig Lernzuwachs und kann belasten; ob Abschaffung Druck senkt, ist kaum belegt. Landesrecht, schnell machbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', 'https://doi.org/10.1016/j.edurev.2021.100401', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10039, 23, 13, 'ST', 'Abitur wieder nach 13 Schuljahren (G9) mit mehr Zeit für Entwicklung und Lernen', '{2304}', 9951, 1, 3, null, 'Mehr Zeit kann Zeitdruck am Gymnasium senken. Studien zur Verkürzung auf G8 finden teils mehr Belastung, teils kaum Effekte auf Gesundheit; Wirkung begrenzt auf Gymnasiasten. Landesrecht, aber Mehrkosten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=60', 'https://doi.org/10.1016/j.econedurev.2017.03.003', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10040, 23, 14, null, 'Lehrausbildung zu einem dualen Lehramtsstudium mit enger Verzahnung von Theorie und Praxis und stärkerem Fokus auf digitale und KI-Kompetenzen weiterentwickeln.', '{2302}', 9962, 1, 2, null, 'Qualifizierung kann Handlungssicherheit verbessern, Wirkung auf Mobbing indirekt. Lehrerbildung ist Ländersache; Bund kann nur über Programme und Vereinbarungen beitragen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10041, 23, 14, null, 'Praxisnahe Aus- und Fortbildung von Lehrkräften, um mehr Freiräume im Lehrberuf zu schaffen.', '{2302}', 9962, 1, 2, null, 'Qualifizierung kann Handlungssicherheit verbessern, Wirkung auf Mobbing indirekt. Lehrerbildung ist Ländersache; Bund kann nur über Programme und Vereinbarungen beitragen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10042, 23, 14, null, 'Notenpflicht spätestens ab der dritten Klasse.', '{2304}', 9957, 0, 1, null, 'Mehr Vergleichs- und Prüfungsdruck mindert Belastung nicht, kann sie erhöhen. Bund hat kaum Zuständigkeit für Schulen, nur über KMK-Einigung der Länder.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10043, 23, 14, null, 'Einheitliche bundesweite Abschlussprüfungen (Deutschland-Abitur).', '{2304}', 9957, 0, 1, null, 'Mehr Vergleichs- und Prüfungsdruck mindert Belastung nicht, kann sie erhöhen. Bund hat kaum Zuständigkeit für Schulen, nur über KMK-Einigung der Länder.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10044, 23, 14, null, 'Schulen sollen mit einem frei einsetzbaren Budget unter anderem über die Länge der gymnasialen Laufbahn (G8/G9) entscheiden.', '{2304}', null, 1, 1, null, 'Entscheidung über G8/G9 kann Zeitdruck mindern, Studien zu G8/G9 sind uneinheitlich. Schulstruktur ist Landessache; ein Bundesbudget mit solcher Entscheidungsfreiheit braucht Länderzustimmung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10045, 23, 14, 'BE', 'Verpflichtende, bedarfsgerechte Fortbildung für alle Lehrkräfte mit Pflichtkontingent und regelmäßiger Überprüfung.', '{2302}', 9960, 1, 3, null, 'Mehr Qualifizierung kann den Umgang mit Konflikten verbessern, ohne Mobbing-Bezug bleibt die Wirkung indirekt und kaum untersucht. Landesrecht, rasch machbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=10', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10046, 23, 14, 'BE', 'Lehramtsstudium praxisnäher: fester Schultag ab Studienbeginn.', '{2302}', 9961, 1, 2, null, 'Mehr Praxis und Klassenführung können Handlungssicherheit erhöhen; Wirkung auf Mobbing nicht untersucht, wirkt erst mit Jahren Verzug. Hochschulreformen und Neugründungen brauchen mehrere Jahre.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=10', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10047, 23, 14, 'BE', 'Gymnasien sollen die Möglichkeit erhalten, zu G9 zurückzukehren.', '{2304}', 9951, 1, 3, null, 'Mehr Zeit kann Zeitdruck am Gymnasium senken. Studien zur Verkürzung auf G8 finden teils mehr Belastung, teils kaum Effekte auf Gesundheit; Wirkung begrenzt auf Gymnasiasten. Landesrecht, aber Mehrkosten.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=11', 'https://doi.org/10.1016/j.econedurev.2017.03.003', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10048, 23, 14, 'BE', 'Anti-Gewalt-Trainings der Polizei im Schulunterricht und Informationsveranstaltungen ausbauen; Verzahnung von Polizei, Schulen und Jugendhilfe.', '{2301}', 9966, 2, 3, null, 'Mehrere Meta-Analysen finden bei schulweiten Programmen weniger Mobbing. Wirkung hängt von Qualität und Dauer ab, Einzelaktionen haben wenig Effekt. Landesrecht, finanzierbar.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=68', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356322/', 'belegt', '2026-10-14', false, true, 'blind'),
  (10049, 23, 14, 'MV', 'Prävention von Mobbing, Cybermobbing und Gewalt an Schulen stärken und den Zugang zu Unterstützungsangeboten verbessern.', '{2301}', 9966, 2, 3, null, 'Mehrere Meta-Analysen finden bei schulweiten Programmen weniger Mobbing. Wirkung hängt von Qualität und Dauer ab, Einzelaktionen haben wenig Effekt. Landesrecht, finanzierbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=87', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356322/', 'belegt', '2026-10-14', false, true, 'blind'),
  (10050, 23, 14, 'MV', 'Schulordnungen auf wenige klare, rechtssichere Regeln konzentrieren; Gewalt und Mobbing mit verbindlichen, abgestuften Reaktionswegen regeln.', '{2301,2302}', 9971, 2, 3, null, 'Verbindliches Eingreifen verhindert Verfestigung; klare Verfahren erhöhen die Handlungssicherheit. Wirkung hängt von Umsetzung und Schulung ab. Landesrecht, schnell machbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=89', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5363950/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10051, 23, 14, 'MV', 'Fortbildungsangebote zu Deeskalation, Notfallmanagement und Umgang mit Gewaltvorfällen verbindlich in die schulische Qualitätsentwicklung einbinden.', '{2302}', 9959, 2, 3, null, 'Geschulte Lehrkräfte greifen häufiger und wirksamer ein, ein Kernfaktor gegen Verfestigung. Reine Einzelschulungen ohne schulweites Konzept zeigen kleinere Effekte. Landesrecht, rasch machbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=89', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10052, 23, 14, 'MV', 'Schulrechtliche Instrumente an allen Schulen rechtssicher anwendbar machen, mit standardisierten Verfahren und Unterstützung durch Schulaufsicht.', '{2302}', 9971, 2, 3, null, 'Verbindliches Eingreifen verhindert Verfestigung; klare Verfahren erhöhen die Handlungssicherheit. Wirkung hängt von Umsetzung und Schulung ab. Landesrecht, schnell machbar.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=89', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5363950/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10053, 23, 14, 'MV', 'Jede Schule erhält eine Kraft für Schulsozialarbeit, die bei komplexen sozialen Konflikten unterstützt.', '{2302}', 9944, 2, 2, null, 'Dauerhaft präsentes Fachpersonal kann Konflikte früh bearbeiten und Betroffene stützen. Die Studienlage zur Schulsozialarbeit ist uneinheitlich, Fachkräfte fehlen, die Finanzierung ist Ländersache.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=97', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10054, 23, 14, 'MV', 'Vor dem Wechsel auf das Gymnasium sollen Prüfungen nach transparenten Bildungsstandards bestanden werden müssen.', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=86', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10055, 23, 14, 'MV', 'Gymnasien sollen selbst entscheiden können, ob sie einen sechs- oder einen siebenjährigen Bildungsweg bis zum Abitur anbieten.', '{2304}', 9951, 1, 3, null, 'Mehr Zeit kann Zeitdruck am Gymnasium senken. Studien zur Verkürzung auf G8 finden teils mehr Belastung, teils kaum Effekte auf Gesundheit; Wirkung begrenzt auf Gymnasiasten. Landesrecht, aber Mehrkosten.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=86', 'https://doi.org/10.1016/j.econedurev.2017.03.003', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10056, 23, 14, 'MV', 'Schulpsychologische Strukturen effizienter organisieren, digitale Erstberatung ausbauen und Standards für akute Belastungslagen festlegen.', '{2304}', 9945, 1, 2, null, 'Mehr Beratung lindert Belastungsfolgen, ändert aber den Leistungs- und Prüfungsdruck selbst kaum. Fachkräftemangel bei Schulpsychologie bremst den Ausbau.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=101', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9765869/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10057, 23, 14, 'ST', 'Diskriminierung in der Jugendarbeit und in der Schule entgegenwirken und für Toleranz und Akzeptanz werben.', '{2301}', 9967, 1, 3, null, 'Projekte können Normen verändern, kurze Einzelaktionen zeigen aber oft nur geringe, kurzlebige Effekte. Landesrecht, rasch machbar.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=37', 'https://doi.org/10.1146/annurev-psych-071620-030619', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10058, 23, 15, null, 'Disziplinarrechte und rechtliche Sicherheit der Lehrkräfte und Schulen stärken.', '{2301,2302}', null, 1, 1, null, 'Disziplinarrechte können Grenzen setzen, Studien zu härteren Sanktionen zeigen kein besseres Klima. Schulrecht ist Landesrecht, dem Bund fehlt die Zuständigkeit.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=162', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10059, 23, 15, null, 'Bildungsstandards aller Schulformen anheben, statt Leistungsanforderungen zu senken.', '{2304}', 9957, 0, 1, null, 'Mehr Vergleichs- und Prüfungsdruck mindert Belastung nicht, kann sie erhöhen. Bund hat kaum Zuständigkeit für Schulen, nur über KMK-Einigung der Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=159', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10060, 23, 15, null, 'Verbindliche Kriterien für den Übergang auf das Gymnasium festlegen.', '{2304}', 9957, 0, 1, null, 'Mehr Vergleichs- und Prüfungsdruck mindert Belastung nicht, kann sie erhöhen. Bund hat kaum Zuständigkeit für Schulen, nur über KMK-Einigung der Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=160', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10061, 23, 15, null, 'Klassenstärken an allen Schulformen verringern.', '{2301}', null, 1, 1, null, 'Kleinere Klassen geben mehr Raum für Beziehungen, Wirkung auf Mobbing ist kaum belegt. Schulen sind Ländersache, der Bund kann höchstens über Vereinbarungen und Geld beitragen; Lehrkräfte fehlen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=159', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10062, 23, 15, 'BE', 'Übergriffiges Verhalten gegenüber Mitschülern konsequent ahnden; Schulausschluss bei ernstlicher Gefahr für andere Schüler', '{2301}', 9970, 1, 3, null, 'Klare Konsequenzen können Normen stützen; Studien zu Null-Toleranz-Ansätzen und Ausschluss zeigen aber keine Verbesserung des Schulklimas. Landesrecht, rasch machbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=31', 'https://doi.org/10.1037/0003-066x.63.9.852', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10063, 23, 15, 'BE', 'Schulkleidung einführen, damit die Herkunft im Schulalltag nicht im Vordergrund steht', '{2301}', null, 1, 3, null, 'Einheitliche Kleidung kann sichtbare Unterschiede verringern; Studien finden kaum belegten Effekt auf Mobbing, Mobbing-Anlässe verlagern sich. Landesrecht bzw. Schulentscheid, kostengünstig.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=29', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10064, 23, 15, 'BE', 'Lehrkräfteausbildung auf Klassenführung und Stressmanagement ausrichten', '{2302}', 9961, 1, 2, null, 'Mehr Praxis und Klassenführung können Handlungssicherheit erhöhen; Wirkung auf Mobbing nicht untersucht, wirkt erst mit Jahren Verzug. Hochschulreformen und Neugründungen brauchen mehrere Jahre.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=39', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10065, 23, 15, 'BE', 'Schulplätze nach Noten und Wohnortnähe vergeben, Losverfahren abschaffen, Abschulung vom Gymnasium ermöglichen', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=28', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10066, 23, 15, 'BE', 'Notengebung beibehalten; Klassenwiederholung vorschreiben, wo notwendig', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=30', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10067, 23, 15, 'BE', 'Bei neu einzurichtenden Landesjugendspielen Leistungsvergleiche sowie Sieger- und Ehrenurkunden vorsehen', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=65', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10068, 23, 15, 'MV', 'Schulsozialarbeit als Landesaufgabe etablieren und die Zahl der Schulpsychologen dem Bedarf anpassen; Gewaltprobleme an Schulen unterbinden.', '{2301,2302}', 9944, 2, 2, null, 'Dauerhaft präsentes Fachpersonal kann Konflikte früh bearbeiten und Betroffene stützen. Die Studienlage zur Schulsozialarbeit ist uneinheitlich, Fachkräfte fehlen, die Finanzierung ist Ländersache.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10069, 23, 15, 'MV', 'Sanktionsmöglichkeiten der Lehrkräfte gesetzlich stärken; bei Gewalt- und Drogendelikten schneller Schulverweise erteilen.', '{2302,2301}', 9970, 1, 3, null, 'Klare Konsequenzen können Normen stützen; Studien zu Null-Toleranz-Ansätzen und Ausschluss zeigen aber keine Verbesserung des Schulklimas. Landesrecht, rasch machbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=32', 'https://doi.org/10.1037/0003-066x.63.9.852', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10070, 23, 15, 'MV', 'Aufbau einer Pädagogischen Hochschule im Land für die Lehrerausbildung mit starkem Praxisbezug.', '{2302}', 9961, 1, 2, null, 'Mehr Praxis und Klassenführung können Handlungssicherheit erhöhen; Wirkung auf Mobbing nicht untersucht, wirkt erst mit Jahren Verzug. Hochschulreformen und Neugründungen brauchen mehrere Jahre.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=25', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10071, 23, 15, 'MV', 'Aufnahme ins Gymnasium bei Note schlechter als 2,5 über einen zusätzlichen, mehrfach wiederholbaren Eignungstest.', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=27', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10072, 23, 15, 'ST', 'Gewalttäter schneller von der Schule verweisen; bei Wiederholung oder schweren Fällen Überweisung an eine Spezialschule für Gewalttäter', '{2301}', 9970, 1, 3, null, 'Klare Konsequenzen können Normen stützen; Studien zu Null-Toleranz-Ansätzen und Ausschluss zeigen aber keine Verbesserung des Schulklimas. Landesrecht, rasch machbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=89', 'https://doi.org/10.1037/0003-066x.63.9.852', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10073, 23, 15, 'ST', 'Erweiterte Appellationsrechte für Eltern und Schüler bei Fehlverhalten von Lehrkräften und Schulleitungen; Beschwerdestelle am Bildungsministerium', '{2302}', 9964, 1, 3, null, 'Zusätzliche Meldewege senken die Hürde, Vorfälle zu melden; ob dies Mobbing verringert, ist kaum untersucht, die Stelle ersetzt kein Handeln an der Schule. Landesrecht, schnell machbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=86', 'https://doi.org/10.1177/10901981211073734', 'offen', '2026-10-14', false, true, 'blind'),
  (10074, 23, 15, 'ST', 'Landesförderung eines Schulprogramms gegen Rassismus einstellen', '{2301}', null, 0, 3, null, 'Die Streichung der Förderung eines Schulprogramms gegen Rassismus entzieht einem bestehenden Präventionsangebot die Mittel und verbessert nichts. Rechtlich und finanziell einfach umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=77', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10075, 23, 15, 'ST', 'Lehrerausbildung an einer neu zu gründenden pädagogischen Hochschule bündeln', '{2302}', 9961, 1, 2, null, 'Mehr Praxis und Klassenführung können Handlungssicherheit erhöhen; Wirkung auf Mobbing nicht untersucht, wirkt erst mit Jahren Verzug. Hochschulreformen und Neugründungen brauchen mehrere Jahre.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=84', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10076, 23, 15, 'ST', 'Bewertungsschlüssel für alle Schulformen anheben, Prüfung nur mit mindestens der Hälfte der Punkte bestanden', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=74', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10077, 23, 15, 'ST', 'Bundesjugendspiele in Klasse 1 bis 4 wieder als Wettkampf mit Benotung durchführen', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=82', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10078, 23, 15, 'ST', 'Schullaufbahnempfehlung wieder verbindlich machen; zentrale Klassenarbeiten entscheiden über die empfohlene Schulart', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=73', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10079, 23, 15, 'ST', 'Mindestens vier Stunden Sportunterricht pro Woche in jeder Jahrgangsstufe und Schulform', '{2304}', null, 1, 2, null, 'Mehr Bewegung gilt als Ausgleich zu Schulstress, Effekt auf Prüfungsdruck selbst gering. Vier Stunden pro Woche brauchen viele zusätzliche Sportlehrkräfte und Hallenzeiten.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=81', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10080, 23, 16, null, 'Hausaufgaben abschaffen; Einüben und Festigen des Gelernten soll in der Schule stattfinden', '{2304}', null, 1, 1, null, 'Weniger Hausaufgaben entlasten Nachmittage; der Nutzen von Hausaufgaben in der Grundschule gilt als gering, in höheren Klassen als größer. Schulrecht ist Ländersache, der Bund kann es nicht regeln.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10081, 23, 16, 'BE', 'Ziffernnoten bis Klasse 9 durch mündliche und schriftliche Rückmeldungen ersetzen, um Leistungsdruck zu mindern.', '{2304}', 9949, 2, 2, null, 'Weniger Noten nehmen einen Kern des Leistungsdrucks; Studien zeigen teils weniger Prüfungsangst und mehr Lernfreude, andere keinen Effekt. Übergänge und Abschlüsse brauchen weiter Bewertungen, KMK-Abstimmung nötig.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=168', 'https://doi.org/10.1080/10627197.2025.2455128', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10082, 23, 16, 'BE', 'Hausaufgaben abbauen, damit Schüler*innen Freizeit ohne verpflichtende Aufgaben haben.', '{2304}', 9952, 1, 2, null, 'Weniger Hausaufgaben mindern Belastung am Nachmittag; Nutzen von Hausaufgaben in der Grundschule gilt als gering. Begleitete Lernzeit braucht zusätzliches Personal und Geld.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=168', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10083, 23, 16, 'BE', 'Probeunterricht bei der Wahl der weiterführenden Schulform abschaffen.', '{2304}', 9953, 1, 3, null, 'Weniger Auslese in den Klassen 4 bis 6 kann Übergangsdruck mindern; Belege zur Wirkung auf Gesundheit fehlen weitgehend. Landesrecht, kurzfristig umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=161', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10084, 23, 16, 'BE', 'Sitzenbleiben auch an Gymnasien abschaffen.', '{2304}', 9954, 1, 3, null, 'Klassenwiederholung bringt laut Forschung wenig Lernzuwachs und kann belasten; ob Abschaffung Druck senkt, ist kaum belegt. Landesrecht, schnell machbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=162', 'https://doi.org/10.1016/j.edurev.2021.100401', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10085, 23, 16, 'BE', 'Schulformempfehlung umfassender nach Stärken und Klassenkonferenz statt vor allem nach Noten.', '{2304}', 9953, 1, 3, null, 'Weniger Auslese in den Klassen 4 bis 6 kann Übergangsdruck mindern; Belege zur Wirkung auf Gesundheit fehlen weitgehend. Landesrecht, kurzfristig umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=161', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10086, 23, 16, 'BE', 'Flexiblere, zeitgemäße Prüfungsformate etablieren; Zahl der Klassenarbeiten reduzieren prüfen.', '{2304}', 9950, 1, 3, null, 'Ohne konkrete Vorgaben (Zahl der Arbeiten, Ersatz von Noten) bleibt offen, ob der Druck sinkt. Wirkung flexibler Formate auf Stress kaum untersucht. Landesrecht, rasch umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=168', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10087, 23, 16, 'BE', 'Psychische Gesundheit als festen Bestandteil des Unterrichts oder von Projektwochen verankern (Resilienz).', '{2304}', 9946, 1, 3, null, 'Programme stärken den Umgang mit Stress, beseitigen den Druck aber nicht. Einzelne Studien finden Effekte, größere Studien zu Achtsamkeit in Schulen fanden keinen Nutzen. Per Erlass und Fortbildung rasch machbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=137', 'https://doi.org/10.1016/j.jaac.2017.07.780', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10088, 23, 16, 'BE', 'Landesprogramm Psychologie an Schulen mit einer Stelle je 800 Schüler*innen einrichten.', '{2304}', 9945, 1, 2, null, 'Mehr Beratung lindert Belastungsfolgen, ändert aber den Leistungs- und Prüfungsdruck selbst kaum. Fachkräftemangel bei Schulpsychologie bremst den Ausbau.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=158', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9765869/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10089, 23, 16, 'BE', 'Pädagogisches Personal an Schulen zur mentalen Gesundheit von Kindern und Jugendlichen fortbilden.', '{2302}', 9960, 1, 3, null, 'Mehr Qualifizierung kann den Umgang mit Konflikten verbessern, ohne Mobbing-Bezug bleibt die Wirkung indirekt und kaum untersucht. Landesrecht, rasch machbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=158', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10090, 23, 16, 'BE', 'Unabhängige Beschwerde- und Beratungsstelle für Schüler*innen und Eltern einrichten.', '{2302}', 9964, 1, 3, null, 'Zusätzliche Meldewege senken die Hürde, Vorfälle zu melden; ob dies Mobbing verringert, ist kaum untersucht, die Stelle ersetzt kein Handeln an der Schule. Landesrecht, schnell machbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=162', 'https://doi.org/10.1177/10901981211073734', 'offen', '2026-10-14', false, true, 'blind'),
  (10091, 23, 16, 'BE', 'Antidiskriminierungs- und Beschwerdestrukturen auf Einzelschulebene etablieren.', '{2302}', 9964, 1, 3, null, 'Zusätzliche Meldewege senken die Hürde, Vorfälle zu melden; ob dies Mobbing verringert, ist kaum untersucht, die Stelle ersetzt kein Handeln an der Schule. Landesrecht, schnell machbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=162', 'https://doi.org/10.1177/10901981211073734', 'offen', '2026-10-14', false, true, 'blind'),
  (10092, 23, 16, 'BE', 'Außerschulische Angebote zu Mobbing- und Gewaltprävention für Schulen absichern und verstetigen.', '{2301}', 9966, 2, 3, null, 'Mehrere Meta-Analysen finden bei schulweiten Programmen weniger Mobbing. Wirkung hängt von Qualität und Dauer ab, Einzelaktionen haben wenig Effekt. Landesrecht, finanzierbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=163', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356322/', 'belegt', '2026-10-14', false, true, 'blind'),
  (10093, 23, 16, 'BE', 'Schulen bei extrem rechten Vorfällen und Anfeindungen unterstützen: Präventionsangebote, Fortbildungen, Leitlinien.', '{2301,2302}', 9967, 1, 3, null, 'Projekte können Normen verändern, kurze Einzelaktionen zeigen aber oft nur geringe, kurzlebige Effekte. Landesrecht, rasch machbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=164', 'https://doi.org/10.1146/annurev-psych-071620-030619', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10094, 23, 16, 'BE', 'Demokratische Schule stärken; den Klassenrat als zentrales Instrument nutzen.', '{2301}', 9969, 2, 3, null, 'Regelmäßige Klassenrunden bearbeiten Normen und Konflikte und sind Teil wirksamer Anti-Mobbing-Konzepte. Als Einzelmaßnahme sind die Effekte uneinheitlich. Landesrecht, kaum Kosten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=164', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10095, 23, 16, 'BE', 'Schutzkonzepte gegen sexualisierte und körperliche Gewalt für Einrichtungen mit jungen Menschen verpflichtend machen.', '{2302}', 9965, 1, 3, null, 'Verbindliche Konzepte bündeln Prävention, Meldewege und Intervention; Wirkung hängt von der Umsetzung ab und ist kaum untersucht. Landesrecht, rasch machbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=191', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5363950/', 'offen', '2026-10-14', false, true, 'blind'),
  (10096, 23, 16, 'BE', 'Diskriminierungskritische Jugendarbeit und Schulsozialarbeit gegen Ausgrenzung und digitale Gewalt stärken.', '{2301,2302}', 9944, 2, 2, null, 'Dauerhaft präsentes Fachpersonal kann Konflikte früh bearbeiten und Betroffene stützen. Die Studienlage zur Schulsozialarbeit ist uneinheitlich, Fachkräfte fehlen, die Finanzierung ist Ländersache.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=281', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10097, 23, 16, 'MV', 'Klassenleiterstunden verpflichtend machen und als Klassenrat mit allen Schüler:innen gestalten', '{2301}', 9969, 2, 3, null, 'Regelmäßige Klassenrunden bearbeiten Normen und Konflikte und sind Teil wirksamer Anti-Mobbing-Konzepte. Als Einzelmaßnahme sind die Effekte uneinheitlich. Landesrecht, kaum Kosten.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10098, 23, 16, 'MV', 'Diskriminierungsfreier Bereich Schule, in dem queere Schüler:innen geschützt und Lehrkräfte sensibilisiert werden', '{2301,2302}', 9959, 2, 3, null, 'Geschulte Lehrkräfte greifen häufiger und wirksamer ein, ein Kernfaktor gegen Verfestigung. Reine Einzelschulungen ohne schulweites Konzept zeigen kleinere Effekte. Landesrecht, rasch machbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=16', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10099, 23, 16, 'MV', '100 zusätzliche Psychologinnen und Psychologen in Schulen', '{2304}', 9945, 1, 2, null, 'Mehr Beratung lindert Belastungsfolgen, ändert aber den Leistungs- und Prüfungsdruck selbst kaum. Fachkräftemangel bei Schulpsychologie bremst den Ausbau.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=5', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9765869/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10100, 23, 16, 'MV', 'Begrenzung der Leistungskontrollen auf höchstens zwei Klausuren oder Tests pro Woche', '{2304}', null, 2, 3, null, 'Eine feste Obergrenze von zwei Tests pro Woche entlastet Prüfungsphasen unmittelbar; Studien zur Wirkung auf Stress sind kaum vorhanden. Landesrecht, ohne Kosten rasch umsetzbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10101, 23, 16, 'MV', 'Abschaffung der Benotung in Kunst, Musik und Sport, außer in Leistungskursen', '{2304}', 9949, 2, 2, null, 'Weniger Noten nehmen einen Kern des Leistungsdrucks; Studien zeigen teils weniger Prüfungsangst und mehr Lernfreude, andere keinen Effekt. Übergänge und Abschlüsse brauchen weiter Bewertungen, KMK-Abstimmung nötig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', 'https://doi.org/10.1080/10627197.2025.2455128', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10102, 23, 16, 'MV', 'Leitlinien für Pausengestaltung und Ruhe- sowie Gemeinschaftsräume an Schulen', '{2304}', null, 1, 3, null, 'Ruheräume und Pausenleitlinien geben Erholung im Schultag, Wirkung auf Leistungsdruck eher gering und kaum untersucht. Per Erlass und kleinen Umbauten rasch machbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10103, 23, 16, 'MV', 'Resilienzförderung und Lerntrainings in die Rahmenpläne aufnehmen', '{2304}', 9946, 1, 3, null, 'Programme stärken den Umgang mit Stress, beseitigen den Druck aber nicht. Einzelne Studien finden Effekte, größere Studien zu Achtsamkeit in Schulen fanden keinen Nutzen. Per Erlass und Fortbildung rasch machbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', 'https://doi.org/10.1016/j.jaac.2017.07.780', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10104, 23, 16, 'MV', 'Neues Schulfach zu Beziehungen, Sexualkunde und Gesundheit', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (10105, 23, 16, 'ST', 'Multiprofessionelle Teams in Kitas und Schulen sollen Kinder in sozialen und emotionalen Kompetenzen stärken.', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=27', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (10106, 23, 16, 'ST', 'Förderung aller Kinder im inklusiven Regelschulsystem strukturell verbessern, mehr qualifizierte Pädagog:innen einsetzen.', '{2301}', 9958, 1, 2, null, 'Kleinere Klassen geben Lehrkräften mehr Raum für Beziehungen; Wirkung auf Mobbing ist wenig belegt, Effekte auf Lernen sind klein. Erfordert viele zusätzliche Lehrkräfte, die fehlen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=30', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10107, 23, 16, 'ST', 'Lehrkräfte im Seiteneinstieg durch erweitertes Fortbildungsangebot unterstützen.', '{2302}', 9960, 1, 3, null, 'Mehr Qualifizierung kann den Umgang mit Konflikten verbessern, ohne Mobbing-Bezug bleibt die Wirkung indirekt und kaum untersucht. Landesrecht, rasch machbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=34', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10108, 23, 16, 'ST', 'Auszubildende vor Abschlussprüfungen für mehrere Tage freistellen, ohne Nachteile.', '{2304}', null, 1, 1, null, 'Freistellung vor Prüfungen entlastet Auszubildende zeitlich, betrifft aber nicht Schüler allgemeiner Schulen. Ausbildungsrecht ist Bundesrecht, ein Land kann dies nicht allein regeln.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=32', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10109, 23, 17, null, 'Social-Media-Gesetz nach australischem Vorbild, damit Kinder nicht in virtuelle Welten abtauchen', '{2303}', 9972, 1, 1, null, 'Plattformregeln erreichen Cybermobbing an der Quelle, Wirkung von Altersgrenzen ist noch kaum untersucht. Weitgehend EU-Recht (DSA), nationale Alleingänge stoßen an Grenzen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://www.leopoldina.org/fileadmin/Daten/Publikationen/Dokumente/2025_Diskussionspapier_Soziale_Medien.pdf', 'offen', '2026-10-14', false, true, 'blind'),
  (10110, 23, 17, 'BE', 'Mehr Sozialarbeiter an Schulen.', '{2301,2302}', 9944, 2, 2, null, 'Dauerhaft präsentes Fachpersonal kann Konflikte früh bearbeiten und Betroffene stützen. Die Studienlage zur Schulsozialarbeit ist uneinheitlich, Fachkräfte fehlen, die Finanzierung ist Ländersache.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10111, 23, 17, 'BE', 'Flächendeckende Präventions- und Anti-Gewaltprogramme an Schulen einführen.', '{2301}', 9966, 2, 3, null, 'Mehrere Meta-Analysen finden bei schulweiten Programmen weniger Mobbing. Wirkung hängt von Qualität und Dauer ab, Einzelaktionen haben wenig Effekt. Landesrecht, finanzierbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8356322/', 'belegt', '2026-10-14', false, true, 'blind'),
  (10112, 23, 17, 'BE', 'Fortbildungsangebote für Lehrkräfte, Sozialarbeit und Polizei zu Cybermobbing erweitern.', '{2302}', 9959, 2, 3, null, 'Geschulte Lehrkräfte greifen häufiger und wirksamer ein, ein Kernfaktor gegen Verfestigung. Reine Einzelschulungen ohne schulweites Konzept zeigen kleinere Effekte. Landesrecht, rasch machbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10603241/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10113, 23, 17, 'BE', 'Frühere Intervention bei Gewalt an Schulen, intensive soziale Betreuung für Mehrfachtäter.', '{2302}', 9971, 2, 3, null, 'Verbindliches Eingreifen verhindert Verfestigung; klare Verfahren erhöhen die Handlungssicherheit. Wirkung hängt von Umsetzung und Schulung ab. Landesrecht, schnell machbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=40', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5363950/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10114, 23, 17, 'BE', 'Wiedereinführung einer verbindlichen Vorschulphase, die soziales Lernen fördert.', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=14', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (10115, 23, 17, 'BE', 'Leistungsbewertung als Förderinstrument statt Mittel der Selektion.', '{2304}', 9950, 1, 3, null, 'Ohne konkrete Vorgaben (Zahl der Arbeiten, Ersatz von Noten) bleibt offen, ob der Druck sinkt. Wirkung flexibler Formate auf Stress kaum untersucht. Landesrecht, rasch umsetzbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=15', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10116, 23, 17, 'BE', 'Deutliche Entschlackung der Lehrpläne, um Zeit für Wiederholung und individuelle Förderung zu schaffen.', '{2304}', 9948, 1, 3, null, 'Weniger Stoff kann Zeitdruck mindern und Raum für Förderung schaffen. Ob Belastung messbar sinkt, ist kaum untersucht; Wirkung hängt von der Umsetzung im Unterricht ab. Landesrecht, schnell machbar.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=15', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10117, 23, 17, 'MV', 'Multiprofessionelle Teams (Sozialarbeit, Gesundheitsförderung, Schulpsychologie) an Schulen, um psychischen Problemen und Gewalt vorzubeugen und Schüler wie Lehrkräfte zu entlasten', '{2301,2302,2304}', 9944, 2, 2, null, 'Dauerhaft präsentes Fachpersonal kann Konflikte früh bearbeiten und Betroffene stützen. Die Studienlage zur Schulsozialarbeit ist uneinheitlich, Fachkräfte fehlen, die Finanzierung ist Ländersache.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10118, 23, 17, 'MV', 'Mehr Klassennachmittage, gemeinsame Unternehmungen und Aktionen an Schulen', '{2301}', 9969, 2, 3, null, 'Regelmäßige Klassenrunden bearbeiten Normen und Konflikte und sind Teil wirksamer Anti-Mobbing-Konzepte. Als Einzelmaßnahme sind die Effekte uneinheitlich. Landesrecht, kaum Kosten.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10119, 23, 17, 'MV', 'Gewaltschutz, Prävention und soziales Lernen als feste Bestandteile schulischer Bildung ausbauen', '{2301}', 9968, 2, 3, null, 'Meta-Analysen zu schulischen Programmen für soziales Lernen finden besseres Sozialverhalten und weniger Aggression. Wirkung hängt von Dauer und Umsetzung ab. Landesrecht, rasch machbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', 'https://doi.org/10.1111/cdev.13968', 'belegt', '2026-10-14', false, true, 'blind'),
  (10120, 23, 17, 'MV', 'Verbindliche Klassenleiterstunde und feste Sprechzeiten für Klassenleitungen', '{2301}', 9969, 2, 3, null, 'Regelmäßige Klassenrunden bearbeiten Normen und Konflikte und sind Teil wirksamer Anti-Mobbing-Konzepte. Als Einzelmaßnahme sind die Effekte uneinheitlich. Landesrecht, kaum Kosten.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10121, 23, 17, 'MV', 'Schultage nicht verlängern, stattdessen Hausaufgabenbetreuung, damit der Nachmittag frei bleibt', '{2304}', 9952, 1, 2, null, 'Weniger Hausaufgaben mindern Belastung am Nachmittag; Nutzen von Hausaufgaben in der Grundschule gilt als gering. Begleitete Lernzeit braucht zusätzliches Personal und Geld.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=46', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10122, 23, 17, 'MV', 'Rahmenbedingungen für Lehrkräfte verbessern, u. a. durch verpflichtende, praxisnahe Fortbildungen', '{2302}', 9960, 1, 3, null, 'Mehr Qualifizierung kann den Umgang mit Konflikten verbessern, ohne Mobbing-Bezug bleibt die Wirkung indirekt und kaum untersucht. Landesrecht, rasch machbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=47', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10123, 23, 17, 'MV', 'Kleine Klassen mit höchstens 24 Schülerinnen und Schülern', '{2301}', 9958, 1, 2, null, 'Kleinere Klassen geben Lehrkräften mehr Raum für Beziehungen; Wirkung auf Mobbing ist wenig belegt, Effekte auf Lernen sind klein. Erfordert viele zusätzliche Lehrkräfte, die fehlen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=48', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10124, 23, 17, 'MV', 'Prüfungen zur Mittleren Reife auch in Klasse 10 am Gymnasium', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=48', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10125, 23, 17, 'MV', 'Stärkere Leistungsorientierung am Gymnasium mit Punktetabelle für die Leistungsbewertung', '{2304}', 9956, 0, 3, null, 'Höhere Hürden, strengere Schlüssel und mehr Wettbewerb setzen nicht an der Entlastung an und können Druck erhöhen. Landesrecht, leicht umsetzbar; Nutzen für Lernstand ist ein anderes Ziel.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=49', 'https://www.nber.org/papers/w11124', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10126, 23, 17, 'MV', 'Mehr Schulpsychologen und dauerhaft finanzierte Schulsozialarbeit für psychische Gesundheit von Kindern', '{2304}', 9945, 1, 2, null, 'Mehr Beratung lindert Belastungsfolgen, ändert aber den Leistungs- und Prüfungsdruck selbst kaum. Fachkräftemangel bei Schulpsychologie bremst den Ausbau.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9765869/', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10127, 23, 17, 'MV', 'Präventionsangebote zu psychischer Gesundheit, Resilienz und Konfliktbewältigung ausbauen', '{2301,2304}', 9946, 1, 3, null, 'Programme stärken den Umgang mit Stress, beseitigen den Druck aber nicht. Einzelne Studien finden Effekte, größere Studien zu Achtsamkeit in Schulen fanden keinen Nutzen. Per Erlass und Fortbildung rasch machbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=61', 'https://doi.org/10.1016/j.jaac.2017.07.780', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10128, 23, 17, 'MV', 'Verbindliche Sucht- und Gesundheitsprävention in Schulen; Stärkung von Lebens-, Sozial- und Resilienzkompetenzen', '{2304}', 9946, 1, 3, null, 'Programme stärken den Umgang mit Stress, beseitigen den Druck aber nicht. Einzelne Studien finden Effekte, größere Studien zu Achtsamkeit in Schulen fanden keinen Nutzen. Per Erlass und Fortbildung rasch machbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=63', 'https://doi.org/10.1016/j.jaac.2017.07.780', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10129, 23, 17, 'ST', 'Verbindlicher Personalschlüssel für Schulsozialarbeit und Schulpsychologie; jede Schule mindestens eine Schulsozialarbeiterstelle', '{2301,2302}', 9944, 2, 2, null, 'Dauerhaft präsentes Fachpersonal kann Konflikte früh bearbeiten und Betroffene stützen. Die Studienlage zur Schulsozialarbeit ist uneinheitlich, Fachkräfte fehlen, die Finanzierung ist Ländersache.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=47', null, 'gemischt', '2026-10-14', false, true, 'blind'),
  (10130, 23, 17, 'ST', 'Mehr Studienplätze und stärkerer Praxisbezug im Lehramtsstudium für künftige Lehrkräfte', '{2302}', 9961, 1, 2, null, 'Mehr Praxis und Klassenführung können Handlungssicherheit erhöhen; Wirkung auf Mobbing nicht untersucht, wirkt erst mit Jahren Verzug. Hochschulreformen und Neugründungen brauchen mehrere Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', null, 'offen', '2026-10-14', false, true, 'blind'),
  (10131, 23, 17, 'ST', 'Längeres gemeinsames Lernen bis zur 8. Klasse; begründet mit Leistungsdruck und Überforderung', '{2304}', 9955, 1, 2, null, 'Späte Aufteilung kann Selektionsdruck mindern; Studien zur Wirkung auf Stress und Wohlbefinden sind uneinheitlich. Strukturreform braucht mehrere Jahre und Schulraum.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=45', 'https://doi.org/10.3102/00346543221100850', 'gemischt', '2026-10-14', false, true, 'blind'),
  (10132, 23, 17, 'ST', 'Sozialpsychiatrischen Dienst ausbauen und stärker in Jugend- und Schularbeit einbinden', '{2304}', 9945, 1, 2, null, 'Mehr Beratung lindert Belastungsfolgen, ändert aber den Leistungs- und Prüfungsdruck selbst kaum. Fachkräftemangel bei Schulpsychologie bremst den Ausbau.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=59', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9765869/', 'gemischt', '2026-10-14', false, true, 'blind');

